  c=mix(c,c*.8+.11,aFade);
  c+=(h21(floor(xy/(2.*U()))+T(24.)*7.13)-.5)*aGrain*.35;
  c*=1.-aVig*smoothstep(.4,1.05,length(uv0-.5)*1.414);
  return vec4(clamp(c,0.,1.),1.);
}

