  float rm=1.; if(rMode>.5){ vec2 rp=uv0-vec2(rX,rY); float rd=rMode<1.5?length(rp*AS())-rSize:dot(rp,vec2(cos(rAngle*6.2832),sin(rAngle*6.2832))); rm=1.-smoothstep(-rFeather*.5,rFeather*.5+.0001,rd); rm=mix(rm,1.-rm,rInv); }
  c=mix(S(uv0),clamp(c,0.,1.),k*rm);
  /*PRO_CODE*/
  c*=exp2(aExp)*vec3(1.+aTemp*.2+aTint*.08,1.-aTint*.12,1.-aTemp*.2+aTint*.08);
  c=(c-.5)*(1.+aCon)+.5;
  c=mix(vec3(L(c)),c,1.+aSat);
  float ha=aHue*6.2832; vec3 hx=vec3(.57735); c=c*cos(ha)+cross(hx,c)*sin(ha)+hx*dot(hx,c)*(1.-cos(ha));
  c=mix(c,c*.8+.11,aFade);
  c+=(h21(floor(xy/(2.*U()))+T(24.)*7.13)-.5)*aGrain*.35;
  c*=1.-aVig*smoothstep(.4,1.05,length(uv0-.5)*1.414);
  return vec4(clamp(c,0.,1.),1.);
}
